import React,
{
useState
}
from "react";

function NotificationCenter(){

const [notifications]
=
useState([

{
id:1,
message:
"Investment return updated"
},

{
id:2,
message:
"Loan application received"
},

{
id:3,
message:
"New fraud alert generated"
}

]);

return(

<div
className="dropdown"
>

<button
className=
"btn btn-outline-primary dropdown-toggle"
data-toggle="dropdown"
>

Notifications

</button>

<div
className=
"dropdown-menu dropdown-menu-right"
>

{
notifications.map(item=>(

<div
key={item.id}
className="dropdown-item"
>

{item.message}

</div>

))
}

</div>

</div>

);

}

export default NotificationCenter;
